#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void normalize_path(char* file) {
    int len = strlen(file);
    if (len == 0)
        return;

    char* result = (char*)malloc(len + 1);
    if (!result)
        return;

    result[0] = '\0';
    int top = 0;

    char* token = strtok(file, "/");
    while (token != NULL) {
        if (strcmp(token, ".") != 0 && strcmp(token, "") != 0) {
            if (strcmp(token, "..") == 0) {
                if (top > 0)
                    top--;
            } else {
                strcpy(result + top, token);
                top += strlen(token);
                result[top++] = '/';
            }
        }
        token = strtok(NULL, "/");
    }

    if (top > 0) {
        result[top - 1] = '\0';
    } else {
        result[0] = '\0';
    }

    strcpy(file, result);
    free(result);
}

