#define MAX_PATH 1024

void normalize_path(char *file) {
    char normalized[MAX_PATH] = "";
    char *token = strtok(file, "/");
    char *ptr = normalized;

    while (token != NULL) {
        if (strcmp(token, ".") != 0 && strcmp(token, "") != 0) {
            if (strcmp(token, "..") == 0) {
                if (ptr > normalized) {
                    // Remove the last directory
                    while (ptr > normalized && *(ptr - 1) != '/') {
                        ptr--;
                    }
                }
            } else {
                // Append the directory
                strcpy(ptr, token);
                ptr += strlen(token);
                *ptr = '/';
                ptr++;
            }
        }
        token = strtok(NULL, "/");
    }

    if (ptr > normalized && *(ptr - 1) == '/') {
        ptr--;
    }
    *ptr = '\0';

    strcpy(file, normalized);
}

#include <stdio.h>
