#include <string.h>

void normalize_path(char* file) {
    char* src = file;
    char* dst = file;
    char* end = file + strlen(file);

    while (src < end) {
        // Handle multiple slashes
        if (*src == '/' && src + 1 < end && *(src + 1) == '/') {
            src++;
        }
        // Handle leading or standalone '.'
        else if (*src == '.' && (src == file || *(src - 1) == '/') && (src + 1 < end && *(src + 1) == '/' || src + 1 == end)) {
            src++;
        }
        // Handle './' or '/./'
        else if (*src == '.' && src + 1 < end && *(src + 1) == '/' && (src == file || *(src - 1) == '/')) {
            src += 2;
        }
        // Handle relative path resolution: 'xxx/../'
        else if (*src == '.' && src + 2 < end && *(src + 1) == '.' && *(src + 2) == '/' && (src == file || *(src - 1) == '/')) {
            // Move back to the previous directory separator
            while (src > file && *(src - 1) != '/') {
                src--;
            }
            if (src > file) {
                src += 3; // Skip "../"
                dst = src - 1;
            } else {
                src += 3;
            }
        }
        // Handle trailing '/..'
        else if (src + 2 < end && *src == '.' && *(src + 1) == '.' && *(src + 2) == '/' && *(src + 3) == '\0') {
            src += 3;
        }
        else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
}

#include <string.h>
#include <stdlib.h>

void normalize_path(char* file) {
    char* src = file;
    char* dst = file;
    size_t len = strlen(file);
    char* stack = NULL;
    size_t stack_size = 0;
    size_t stack_capacity = 0;

    while (*src) {
        if (*src == '/' && src > file && *(src - 1) == '/') {
            src++;
            continue;
        }

        if (*src == '.' && (src == file || *(src - 1) == '/') && *(src + 1) == '/') {
            src += 2;
            continue;
        }

        if (*src == '.' && *(src - 1) == '/' && *(src + 1) == '.' && (src + 2 == file + len || *(src + 2) == '/')) {
            // Found a "../", need to pop from the stack
            if (stack_size > 0) {
                stack_size--;
                while (stack_size > 0 && stack[stack_size - 1] != '/') {
                    stack_size--;
                }
            }
            src += 3;
            continue;
        }

        if (*src == '/' && stack_size > 0 && stack[stack_size - 1] == '.' && (src + 1 == file + len || *(src + 1) == '/')) {
            // Found "/./", just skip it
            src++;
            continue;
        }

        // Allocate stack if needed
        if (stack_size + 1 > stack_capacity) {
            stack_capacity = stack_size + 1;
            stack = (char*)realloc(stack, stack_capacity);
        }

        stack[stack_size++] = *src;
        src++;
    }

    // Trim trailing slash if needed
    if (stack_size > 0 && stack[stack_size - 1] == '/') {
        stack_size--;
    }

    // Copy normalized path back to original buffer
    for (size_t i = 0; i < stack_size; i++) {
        file[i] = stack[i];
    }
    file[stack_size] = '\0';

    if (stack) {
        free(stack);
    }
}

